import {SqliteAgentNoticeDelivery,createAgentNoticeHttpsTransport,createAgentNoticeHttpsVerifier} from '../../dist/index.js';
const scope={tenantId:'tenant',agentId:'agent'},actor={tenantId:'tenant',principalId:'reviewer'},id=Number(process.env.TEST_DELIVERY),options={scope,destinations:[{id:'channel',url:process.env.TEST_NOTICE_URL,bearerToken:'a'.repeat(32)}],timeoutMs:60000},outbox=new SqliteAgentNoticeDelivery(process.env.TEST_DB,{scope,clock:()=>10,authorize:()=>true});
try{if(process.env.TEST_MODE==='send')await outbox.dispatch(actor,id,createAgentNoticeHttpsTransport(options));else if(process.env.TEST_MODE==='recover'){await outbox.recover(actor,id);const result=await outbox.verifyAndReconcileDelivered(actor,id,createAgentNoticeHttpsVerifier(options));process.stdout.write(JSON.stringify({status:result?.status??'uncertain'})+'\n');}else throw Error('Invalid test mode');}finally{outbox.close();}
